mapper.select:
SELECT transmission_id, req_ctrl_cmd_id, transmission_code, transmission_msg, transmission_time, transmission_url, transmission_param, transmission_result_data FROM event_transmission_result_info where 1=1
and transmission_id = #{transmissionId}
and req_ctrl_cmd_id = #{reqCtrlCmdId}
order by transmission_id desc

